item.text:
Для входа нужен **`ton_proof`**, а не просто адрес из TON Connect. Сервер выдаёт одноразовый challenge, проверяет подпись и привязку ключа к адресу, затем создаёт сессию.

Ниже пример для **V4R2 и V5R1**, Node.js с ESM и Redis ≥6.2. Фронтенд и API доступны на одном HTTPS-origin.

Бэкенд:

```bash
npm i express@5 express-session redis connect-redis @ton/core @ton/ton tweetnacl
```

```js
import express from "express";
import session from "express-session";
import { createClient } from "redis";
import { RedisStore } from "connect-redis";
import { randomBytes, createHash } from "node:crypto";
import { Address, Cell, contractAddress, loadStateInit } from "@ton/core";
import { WalletContractV4, WalletContractV5R1 } from "@ton/ton";
import nacl from "tweetnacl";

const ORIGIN = "https://app.example.com";
const DOMAIN = new URL(ORIGIN).host;
const DOMAIN_BYTES = Buffer.from(DOMAIN, "utf8");
const CHAIN = "-239"; // mainnet
const TTL = 300;      // секунд

// SESSION_SECRET — случайный секрет, одинаковый у всех экземпляров API.
if (!process.env.SESSION_SECRET || !process.env.REDIS_URL) {
  throw new Error("Set SESSION_SECRET and REDIS_URL");
}

const redis = createClient({ url: process.env.REDIS_URL });
redis.on("error", console.error);
await redis.connect();

const app = express();
// Для размещения за одним доверенным HTTPS reverse proxy.
app.set("trust proxy", 1);

app.use("/api", (req, res, next) => {
  res.set("Cache-Control", "no-store");
  if (req.method === "POST" && req.get("origin") !== ORIGIN) {
    return res.sendStatus(403);
  }
  next();
});

app.use(express.json({ limit: "32kb" }));
app.use(session({
  name: "__Host-sid",
  secret: process.env.SESSION_SECRET,
  store: new RedisStore({ client: redis, prefix: "ton:session:" }),
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: true,
    sameSite: "strict",
    path: "/",
    maxAge: 24 * 60 * 60 * 1000,
  },
}));

const sessionCall = (req, method) => new Promise((resolve, reject) => {
  req.session[method](err => err ? reject(err) : resolve());
});
const nonceKey = req => `ton:challenge:${req.sessionID}`;
const sha256 = value => createHash("sha256").update(value).digest();

function check(condition) {
  if (!condition) throw new Error("Invalid ton_proof");
}

// Код кошелька определяет расположение публичного ключа в init.data.
// V4R2: seqno:32 + walletId:32.
// V5R1: signatureAllowed:1 + seqno:32 + walletId:32.
const keyOffsets = new Map([
  [WalletContractV4, 64],
  [WalletContractV5R1, 65],
].map(([Wallet, offset]) => [
  Wallet.create({
    workchain: 0,
    publicKey: Buffer.alloc(32),
  }).init.code.hash().toString("hex"),
  offset,
]));

function verifyProof(body, nonce) {
  const { account, proof } = body ?? {};
  const now = Math.floor(Date.now() / 1000);

  check(typeof nonce === "string" && proof?.payload === nonce);
  check(account?.chain === CHAIN);
  check(proof.domain?.value === DOMAIN);
  check(proof.domain.lengthBytes === DOMAIN_BYTES.length);
  check(
    Number.isSafeInteger(proof.timestamp) &&
    proof.timestamp >= now - TTL &&
    proof.timestamp <= now + 30
  );
  check(typeof proof.signature === "string");

  const address = Address.parse(account.address);

  // Привязываем публичный ключ к адресу через StateInit.
  // account.publicKey намеренно не используем.
  const slice = Cell.fromBase64(account.walletStateInit).beginParse();
  const init = loadStateInit(slice);
  slice.endParse();

  check(init.code && init.data);
  check(
    !init.special &&
    init.splitDepth == null &&
    (init.libraries?.size ?? 0) === 0
  );
  check(contractAddress(address.workChain, init).equals(address));

  const offset = keyOffsets.get(init.code.hash().toString("hex"));
  check(offset !== undefined); // Неизвестный код кошелька отклоняем.
  const publicKey = init.data.beginParse().skip(offset).loadBuffer(32);

  const workchain = Buffer.alloc(4);
  workchain.writeInt32BE(address.workChain);

  const domainLength = Buffer.alloc(4);
  domainLength.writeUInt32LE(DOMAIN_BYTES.length);

  const timestamp = Buffer.alloc(8);
  timestamp.writeBigUInt64LE(BigInt(proof.timestamp));

  const message = Buffer.concat([
    Buffer.from("ton-proof-item-v2/", "utf8"),
    workchain,
    address.hash,
    domainLength,
    DOMAIN_BYTES,
    timestamp,
    Buffer.from(proof.payload, "utf8"),
  ]);

  const digest = sha256(Buffer.concat([
    Buffer.from([0xff, 0xff]),
    Buffer.from("ton-connect", "utf8"),
    sha256(message),
  ]));

  const signature = Buffer.from(proof.signature, "base64");
  check(signature.length === 64);
  check(nacl.sign.detached.verify(digest, signature, publicKey));

  return address.toRawString();
}

app.post("/api/auth/challenge", async (req, res) => {
  // Сохраняем pre-auth сессию, чтобы браузер получил HttpOnly cookie.
  req.session.preAuth = true;
  await sessionCall(req, "save");

  const payload = randomBytes(32).toString("hex");
  await redis.set(nonceKey(req), payload, { EX: TTL });
  res.json({ payload });
});

app.post("/api/auth/verify", async (req, res) => {
  // GETDEL атомарен: challenge расходуется при первой попытке проверки.
  const nonce = await redis.getDel(nonceKey(req));

  let address;
  try {
    address = verifyProof(req.body, nonce);
  } catch {
    return res.sendStatus(401);
  }

  // Меняем идентификатор сессии после успешной аутентификации.
  await sessionCall(req, "regenerate");
  req.session.user = { address, chain: CHAIN };
  await sessionCall(req, "save");

  res.json(req.session.user);
});

app.get("/api/me", (req, res) => {
  if (!req.session.user) return res.sendStatus(401);
  res.json(req.session.user);
});

app.use((err, req, res, next) => {
  console.error(err);
  res.sendStatus(500);
});

app.listen(3000);
```

Фронтенд:

```bash
npm i @tonconnect/ui-react
```

```jsx
import { useEffect, useRef, useState } from "react";
import {
  TonConnectUIProvider,
  useTonConnectUI,
} from "@tonconnect/ui-react";

async function post(path, body = {}) {
  const response = await fetch(path, {
    method: "POST",
    credentials: "same-origin",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!response.ok) throw new Error("Вход не выполнен. Попробуйте снова.");
  return response.json();
}

function Login() {
  const [ui] = useTonConnectUI();
  const pendingPayload = useRef(null);
  const [message, setMessage] = useState("");

  useEffect(() => ui.onStatusChange(async wallet => {
    // Восстановленное подключение само по себе не выполняет вход.
    if (!wallet || !pendingPayload.current) return;

    const expectedPayload = pendingPayload.current;
    pendingPayload.current = null;

    try {
      const item = wallet.connectItems?.tonProof;
      if (
        !item ||
        !("proof" in item) ||
        item.proof.payload !== expectedPayload
      ) {
        throw new Error("Кошелёк не предоставил запрошенный ton_proof.");
      }

      const user = await post("/api/auth/verify", {
        account: wallet.account,
        proof: item.proof,
      });

      setMessage(`Выполнен вход: ${user.address}`);
    } catch (error) {
      setMessage(error.message);
    }
  }), [ui]);

  async function login() {
    try {
      setMessage("");
      pendingPayload.current = null;

      // Для нового входа запрашиваем новое доказательство.
      if (ui.connected) await ui.disconnect();

      ui.setConnectRequestParameters({ state: "loading" });
      const { payload } = await post("/api/auth/challenge");

      pendingPayload.current = payload;
      ui.setConnectRequestParameters({
        state: "ready",
        value: { tonProof: payload },
      });

      await ui.openModal();
    } catch (error) {
      pendingPayload.current = null;
      setMessage(error.message);
    }
  }

  return (
    <>
      <button onClick={login}>Войти через TON</button>
      <p role="status">{message}</p>
    </>
  );
}

export default function App() {
  return (
    <TonConnectUIProvider
      manifestUrl="https://app.example.com/tonconnect-manifest.json"
    >
      <Login />
    </TonConnectUIProvider>
  );
}
```

По указанному URL должен быть публично доступен манифест:

```json
{
  "url": "https://app.example.com",
  "name": "Наше приложение",
  "iconUrl": "https://app.example.com/icon.png"
}
```

Сервер проверяет **домен, время, одноразовый challenge, Ed25519-подпись и соответствие `StateInit` адресу**. Разрешённый код кошелька позволяет достоверно извлечь ключ из его данных. Для остальных версий кошельков нужно добавить проверку их кода и соответствующий разбор данных. После входа API использует серверную сессию; переданный клиентом адрес сам по себе авторизацией не считается.

